4190: 		/*
4191: 		 * On RT, prevent a live lock when %current preempted soft
4192: 		 * interrupt processing or prevents ksoftirqd from running by
4193: 		 * keeping flipping BH. If the BH work item runs on a different
4194: 		 * CPU then this has no effect other than doing the BH
4195: 		 * disable/enable dance for nothing. This is copied from
4196: 		 * kernel/softirq.c::tasklet_unlock_spin_wait().
4197: 		 */
4198: 		while (!try_wait_for_completion(&barr.done)) {
4199: 			if (IS_ENABLED(CONFIG_PREEMPT_RT)) {
4200: 				local_bh_disable();
4201: 				local_bh_enable();
4202: 			} else {
4203: 				cpu_relax();
4204: 			}
4205: 		}
4206: 	} else {
4207: 		wait_for_completion(&barr.done);
4208: 	}
4209: 
4210: 	destroy_work_on_stack(&barr.work);
4211: 	return true;
4212: }

